@namespace sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var status = step < CurrentStep ? "completed" :
                     step == CurrentStep ? "active" : "future";
        var clickable = step < CurrentStep;

        <div class="step @status" @onclick="() => { if (clickable) OnStepClicked.InvokeAsync(step); }">
            <div class="step-circle">
                @if (status == "completed")
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <div class="step-label">@StepNames[step - 1]</div>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(step < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Company" @onchange="e => { Company = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Title" @onchange="e => { Title = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString(\"yyyy-MM-dd\")); NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" />
            }
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => { Description = e.Value?.ToString() ?? \"\"; NotifyChanged(); }"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, IsCurrent ? null : EndDate, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
}

@namespace sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Components.Pages.Apply

<div class="reference-form">
    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Name" @onchange="e => { Name = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Relationship" @onchange="e => { Relationship = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Email" @onchange="e => { Email = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Phone" @onchange="e => { Phone = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

