@namespace sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p>Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm
                Name="@reference.Name"
                Relationship="@reference.Relationship"
                Email="@reference.Email"
                Phone="@reference.Phone"
                CanRemove="@(References.Count > 1)"
                OnRemove="() => RemoveReference(index)"
                OnChanged="data => UpdateReference(index, data)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new() { new(), new() };
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        References[index] = new ReferenceModel
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        var hasValid = References.Any(r => !string.IsNullOrWhiteSpace(r.Name) && !string.IsNullOrWhiteSpace(r.Email));
        if (!hasValid)
        {
            ValidationError = "Please provide at least one reference with name and email.";
            return;
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" maxlength="2000" @bind="CoverLetterText" @bind:event="oninput"></textarea>
        <div class="char-count">@CoverLetterText.Length / 2000 characters</div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task HandleNext()
    {
        ValidationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetterText);
    }
}

