arguments.file_text:
@page "/apply"
@using sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Components.Pages.Apply
@using sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Models
@using sv_82a0ce9be4ab41a9a19fdfa3eef09a89.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalNext" />
            break;

        case 2:
            <WorkHistoryStep
                Entries="@workEntries"
                OnNext="HandleWorkNext"
                OnBack="() => currentStep = 1" />
            break;

        case 3:
            <ReferencesStep
                References="@references"
                OnNext="HandleReferencesNext"
                OnBack="() => currentStep = 2" />
            break;

        case 4:
            <CoverLetterStep
                CoverLetterText="@coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="() => currentStep = 3" />
            break;

        case 5:
            <ReviewStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                WorkEntries="@workEntries"
                References="@references"
                CoverLetter="@coverLetter"
                IsSubmitting="@isSubmitting"
                IsSubmitted="@isSubmitted"
                ApplicationId="@applicationId"
                SubmitError="@submitError"
                OnBack="() => currentStep = 4"
                OnEditSection="GoToStep"
                OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 1;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (step >= 1 && step < currentStep)
            currentStep = step;
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        currentStep = 2;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 4;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 5;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var workHistory = new WorkHistory(
                workEntries
                    .Where(e => !string.IsNullOrWhiteSpace(e.Company))
                    .Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description))
                    .ToList());

            var refList = references
